use strict; use warnings;
my $BIN="/workspace/dataset/test16_executable";
sub run { my ($arg)=@_; my $pid=open(my $fh,"-|"); if($pid==0){ open(STDERR,">&",\*STDOUT); exec($BIN,$arg) or exit(127);} local $/; my $o=<$fh>; close $fh; return $o//''; }
sub esc { my $s=shift; $s=~s/([^\x20-\x7e])/sprintf("\\x%02x",ord($1))/ge; return $s; }
sub model { my $u=shift; my $iq=index($u,'?'); my $if=index($u,'#'); my @c=grep{$_>=0}($iq,$if);
  my $cut=@c?(sort{$a<=>$b}@c)[0]:length($u); my $s=substr($u,0,$cut); my $path; my $i=index($s,'://');
  if($i>=0){ my $rest=substr($s,$i+3); my $j=index($rest,'/'); $path=($j>=0)?substr($rest,$j):''; } else {$path=$s;}
  return grep{length($_)>0} split(/\//,$path,-1); }
# raw-output comparison; alphabet includes newline, CR, tab, NBSP, invalid UTF-8
my @alpha=('/','/','a','?','#',':','%','2','F',"\n","\r","\t"," ","\x0b","\x0c","\xa0","\xff","\xc3","\xa9","\xe2","\x80","+",'.','\\','e','.','c','o','m','h','t','p');
srand(4242);
my ($n,$bad)=(0,0);
for my $i (1..5000){
  my $len=1+int(rand(18)); my $u=''; $u.=$alpha[int(rand(scalar @alpha))] for(1..$len);
  my @exp=model($u);
  # need lines 1-4 too; derive expected tail only and compare suffix
  my $tail=scalar(@exp)."\n".join("",map{$_."\n"}@exp);
  my $o=run($u); $n++;
  # lines1-4 are 4 lines of 0/1 => first 8 chars
  my $got=length($o)>=8?substr($o,8):'';
  if($got ne $tail){ $bad++; print "MISMATCH u=".esc($u)."\n  got=".esc($got)."\n  exp=".esc($tail)."\n"; last if $bad>10; }
}
print "raw fuzz (ctrl+highbytes): $n probes, $bad mismatches\n";
